import data from './talentTree.json';

// The Warlock talent tree and the talent string codec (stage 2b, Task 1). Pure, framework-free and
// total: every function accepts hostile input (strings from storage or imports, rank maps with
// unknown or prototype keys, throwing proxies) and answers with error strings instead of throwing.
// Data: talentTree.json, generated by scripts/build-talent-tree.mjs from wowsims tbc-new
// ui/sim/talents/trees/warlock.json (MIT) and Wowhead TBC tooltips. See docs/data-sources.md,
// "Part I: talents".

/** One talent. Tree, row and column are 0-based (row 0 is the top of the tree). */
export interface TalentDef {
  /** wowsims `fieldName` (proto WarlockTalents field, camelCase): the stable id. */
  id: string;
  name: string;
  /** 0 Affliction, 1 Demonology, 2 Destruction. */
  tree: 0 | 1 | 2;
  row: number;
  col: number;
  maxRank: number;
  /** Id of the talent (same tree, higher row) that must be at its maximum rank first. */
  prereq?: string;
  /** Wowhead icon name: public/icons/talents/<icon>.jpg (`npm run icons`). */
  icon: string;
  /** TBC spell id of each rank (rank 1 first). */
  wowheadIds: number[];
  /** Wowhead tooltip text of each rank (plain text; '' when the tooltip was unavailable). */
  descriptions: string[];
}

export interface TalentTreeDef {
  name: string;
  talents: readonly TalentDef[];
}

/** The three trees in talent string order. Shared data: do not mutate. */
export const TALENT_TREE: { source: string; trees: readonly TalentTreeDef[] } = data as {
  source: string;
  trees: TalentTreeDef[];
};

/** Talent points at level 70 (one per level from 10 to 70). Source: Wowhead TBC talent calculator. */
export const TALENT_POINTS_MAX = 61;
/** A talent in row N needs 5 x N points spent in the rows above it, in its tree (TBC rule). */
const POINTS_PER_ROW = 5;
/** Longest talent string accepted (a full string is 66 characters). */
export const TALENT_STRING_MAX_LENGTH = 200;
/** Error lists stop after this many entries (plus one "... and N more problems." line). */
const MAX_ERRORS = 20;

// Indexes built on first use, not at module load: a module whose top level only binds the JSON is
// side-effect free, so a bundle that does not call the codec leaves the tree data out.
let index: { all: readonly TalentDef[]; byId: ReadonlyMap<string, TalentDef> } | undefined;
function talentIndex() {
  if (!index) {
    const all = TALENT_TREE.trees.flatMap((t) => t.talents);
    index = { all, byId: new Map(all.map((d) => [d.id, d])) };
  }
  return index;
}

/** The talent with this id (prototype-safe: a Map lookup), or undefined. */
export function talentById(id: unknown): TalentDef | undefined {
  return typeof id === 'string' ? talentIndex().byId.get(id) : undefined;
}

/** Where `npm run icons` stores a talent icon, relative to the app's base URL. */
export function talentIconPath(icon: string): string {
  return `icons/talents/${icon}.jpg`;
}

/** Talent ranks by talent id (missing = 0). Untrusted when it comes from outside. */
export type TalentRanks = Readonly<Record<string, number>>;
export type TalentCheck = { ok: true } | { ok: false; reason: string };
export interface DecodedTalents {
  /** Every talent id, in string order, with its rank as read (all 0 when the string is malformed). */
  ranks: Record<string, number>;
  /** Points per tree (Affliction, Demonology, Destruction). */
  points: [number, number, number];
  /** Every problem of the string: format errors, or else rule violations (validateTalents). */
  errors: string[];
}

// ---------------------------------------------------------------------------------------------
// Reading untrusted rank maps

const NOT_OBJECT = 'Talent ranks must be an object.';
const UNREADABLE = 'Talent ranks could not be read.';

interface ReadRanks {
  /** Own values of the known talents, as given (not yet checked). */
  values: Map<string, unknown>;
  /** The first MAX_ERRORS unknown own keys, and how many there are. */
  unknown: string[];
  unknownCount: number;
}

/** Own, known keys only (never the prototype chain); a reason string when it cannot be read. */
function readRanks(ranks: unknown): ReadRanks | string {
  if (typeof ranks !== 'object' || ranks === null || Array.isArray(ranks)) return NOT_OBJECT;
  try {
    const values = new Map<string, unknown>();
    for (const d of talentIndex().all) {
      if (Object.prototype.hasOwnProperty.call(ranks, d.id)) values.set(d.id, (ranks as Record<string, unknown>)[d.id]);
    }
    const unknown: string[] = [];
    let unknownCount = 0;
    for (const key of Object.keys(ranks)) {
      if (talentIndex().byId.has(key)) continue;
      unknownCount++;
      if (unknown.length < MAX_ERRORS) unknown.push(key);
    }
    return { values, unknown, unknownCount };
  } catch {
    return UNREADABLE;
  }
}

/** A well-formed rank: a whole number >= 0 (it may still be above the talent's maximum). */
function isRank(value: unknown): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= 0;
}

/** The rank as validation counts it: as given when well formed, 0 otherwise. */
function countedRank(read: ReadRanks, d: TalentDef): number {
  const v = read.values.get(d.id);
  return isRank(v) ? v : 0;
}

/** The rank clamped to 0..maxRank (malformed = 0): what the editor and the encoder use. */
function clampedRank(read: ReadRanks, d: TalentDef): number {
  return Math.min(countedRank(read, d), d.maxRank);
}

/** A key or id shown in a message: at most 40 characters, printable ASCII only. */
function label(text: string): string {
  const chars = [...text];
  const shown = chars.slice(0, 40).map((c) => (/^[\x20-\x7e]$/.test(c) ? c : '?')).join('');
  return chars.length > 40 ? `${shown}...` : shown;
}

/** Points spent in each row (0-8) of a tree. */
function rowPoints(read: ReadRanks, tree: number, rank: (read: ReadRanks, d: TalentDef) => number): number[] {
  const rows = new Array<number>(9).fill(0);
  for (const d of TALENT_TREE.trees[tree]?.talents ?? []) rows[d.row] = (rows[d.row] ?? 0) + rank(read, d);
  return rows;
}

const pointsAbove = (rows: number[], row: number) => rows.slice(0, row).reduce((a, b) => a + b, 0);
const treeName = (d: TalentDef) => TALENT_TREE.trees[d.tree]?.name ?? '';
const rowMessage = (d: TalentDef, above: number) =>
  `${d.name} needs ${POINTS_PER_ROW * d.row} points in ${treeName(d)} rows above it (has ${above}).`;
const prereqMessage = (d: TalentDef, p: TalentDef, rank: number) =>
  `${d.name} needs ${p.name} at full rank (${rank}/${p.maxRank}).`;

// ---------------------------------------------------------------------------------------------
// Validation

function ruleErrors(ranks: unknown): string[] {
  const read = readRanks(ranks);
  if (typeof read === 'string') return [read];
  const errors: string[] = [];
  let total = 0;
  for (const key of read.unknown) errors.push(`Unknown talent '${label(key)}'.`);
  TALENT_TREE.trees.forEach((tree, t) => {
    const rows = rowPoints(read, t, countedRank);
    for (const d of tree.talents) {
      const value = read.values.get(d.id);
      if (value !== undefined && !isRank(value)) {
        errors.push(`${d.name}: rank must be a whole number from 0 to ${d.maxRank}.`);
        continue;
      }
      const rank = value ?? 0;
      total += rank;
      if (rank > d.maxRank) errors.push(`${d.name}: rank ${rank} is above the maximum ${d.maxRank}.`);
      if (rank === 0) continue;
      const above = pointsAbove(rows, d.row);
      if (above < POINTS_PER_ROW * d.row) errors.push(rowMessage(d, above));
      const p = talentById(d.prereq);
      if (p && countedRank(read, p) < p.maxRank) errors.push(prereqMessage(d, p, countedRank(read, p)));
    }
  });
  if (total > TALENT_POINTS_MAX) errors.push(`Too many points: ${total} spent, at most ${TALENT_POINTS_MAX}.`);
  const problems = errors.length + read.unknownCount - read.unknown.length;
  if (problems <= MAX_ERRORS) return errors;
  return [...errors.slice(0, MAX_ERRORS), `... and ${problems - MAX_ERRORS} more problems.`];
}

/**
 * Every rule a build breaks, as stable English sentences ([] = valid): unknown talents, malformed
 * ranks, ranks above the maximum, row requirements (5 points per row above, in the same tree),
 * prerequisites not at full rank, more than 61 points. A string is decoded first (format errors).
 */
export function validateTalents(input: string | TalentRanks): string[] {
  return typeof input === 'string' ? decodeTalents(input).errors : ruleErrors(input);
}

// ---------------------------------------------------------------------------------------------
// String codec

function zeroRanks(): Record<string, number> {
  const ranks: Record<string, number> = {};
  for (const d of talentIndex().all) ranks[d.id] = 0;
  return ranks;
}

/** A character shown in a message: quoted when printable ASCII, else its code point. */
function showChar(c: string): string {
  if (/^[\x20-\x7e]$/.test(c)) return `'${c}'`;
  return `U+${(c.codePointAt(0) ?? 0).toString(16).toUpperCase().padStart(4, '0')}`;
}

function formatError(error: string): DecodedTalents {
  return { ranks: zeroRanks(), points: [0, 0, 0], errors: [error] };
}

/**
 * Reads a talent string `affliction-demonology-destruction`: one digit per talent in tree order
 * (TALENT_ORDER); a tree may be shorter (missing trailing digits are 0) or empty. Surrounding
 * whitespace is ignored. A malformed string gives all-zero ranks and one format error; a well-formed
 * one gives its ranks as read (even above a maximum) and the rule violations as `errors`.
 */
export function decodeTalents(text: string): DecodedTalents {
  if (typeof text !== 'string') return formatError('Talent string must be text.');
  if (text.length > TALENT_STRING_MAX_LENGTH) {
    return formatError(`Talent string is too long (${text.length} characters, at most ${TALENT_STRING_MAX_LENGTH}).`);
  }
  const parts = text.trim().split('-');
  if (parts.length !== TALENT_TREE.trees.length) {
    return formatError(`Talent string needs 3 trees separated by '-' (got ${parts.length}).`);
  }
  const ranks = zeroRanks();
  const points = [0, 0, 0];
  for (const [t, tree] of TALENT_TREE.trees.entries()) {
    const chars = [...(parts[t] ?? '')];
    if (chars.length > tree.talents.length) {
      return formatError(`${tree.name}: ${chars.length} digits, the tree has ${tree.talents.length} talents.`);
    }
    for (const [i, c] of chars.entries()) {
      if (c < '0' || c > '9' || c.length !== 1) return formatError(`${tree.name}: unexpected character ${showChar(c)} at position ${i + 1}.`);
      const d = tree.talents[i];
      if (d) ranks[d.id] = Number(c);
      points[t] = (points[t] ?? 0) + Number(c);
    }
  }
  return { ranks, points: [points[0] ?? 0, points[1] ?? 0, points[2] ?? 0], errors: ruleErrors(ranks) };
}

/**
 * The talent string of a build: every tree at full width (21/22/21 digits, trailing zeros kept,
 * like the WowSimsExporter string of the author's build). Lossy only for input it cannot represent:
 * ranks are clamped to 0..maxRank (malformed ranks are 0) and unknown keys are dropped.
 */
export function encodeTalents(ranks: TalentRanks): string {
  const read = readRanks(ranks);
  return TALENT_TREE.trees
    .map((tree) => tree.talents.map((d) => (typeof read === 'string' ? 0 : clampedRank(read, d))).join(''))
    .join('-');
}

// ---------------------------------------------------------------------------------------------
// Editor checks (one point at a time)

function lookUp(ranks: unknown, id: unknown): { read: ReadRanks; d: TalentDef } | { ok: false; reason: string } {
  if (typeof id !== 'string') return { ok: false, reason: 'Unknown talent.' };
  const d = talentIndex().byId.get(id);
  if (!d) return { ok: false, reason: `Unknown talent '${label(id)}'.` };
  const read = readRanks(ranks);
  if (typeof read === 'string') return { ok: false, reason: read };
  return { read, d };
}

/**
 * Whether one more point can go into `id`: below its maximum rank, fewer than 61 points spent,
 * the row requirement met and the prerequisite at full rank. Ranks are read clamped to 0..maxRank.
 */
export function canAddPoint(ranks: TalentRanks, id: string): TalentCheck {
  const found = lookUp(ranks, id);
  if ('ok' in found) return found;
  const { read, d } = found;
  const rank = clampedRank(read, d);
  if (rank >= d.maxRank) return { ok: false, reason: `${d.name} is at its maximum rank (${rank}/${d.maxRank}).` };
  const total = talentIndex().all.reduce((n, o) => n + clampedRank(read, o), 0);
  if (total >= TALENT_POINTS_MAX) return { ok: false, reason: `All ${TALENT_POINTS_MAX} talent points are spent.` };
  const above = pointsAbove(rowPoints(read, d.tree, clampedRank), d.row);
  if (above < POINTS_PER_ROW * d.row) return { ok: false, reason: rowMessage(d, above) };
  const p = talentById(d.prereq);
  if (p && clampedRank(read, p) < p.maxRank) return { ok: false, reason: prereqMessage(d, p, clampedRank(read, p)) };
  return { ok: true };
}

/**
 * Whether one point can come out of `id` without breaking the build: no talent with points needs
 * `id` at full rank (its prerequisite), and every talent with points in a lower row of the tree
 * still has 5 points per row above it once the point is gone (the cumulative row check).
 */
export function canRemovePoint(ranks: TalentRanks, id: string): TalentCheck {
  const found = lookUp(ranks, id);
  if ('ok' in found) return found;
  const { read, d } = found;
  if (clampedRank(read, d) === 0) return { ok: false, reason: `${d.name} has no points to remove.` };
  const tree = TALENT_TREE.trees[d.tree]?.talents ?? [];
  for (const o of tree) {
    if (o.prereq === d.id && clampedRank(read, o) > 0) {
      return { ok: false, reason: `${o.name} depends on ${d.name} at full rank.` };
    }
  }
  const rows = rowPoints(read, d.tree, clampedRank);
  rows[d.row] = (rows[d.row] ?? 0) - 1;
  for (const o of tree) {
    if (o.row <= d.row || clampedRank(read, o) === 0) continue;
    if (pointsAbove(rows, o.row) < POINTS_PER_ROW * o.row) {
      return {
        ok: false,
        reason: `${o.name} needs ${POINTS_PER_ROW * o.row} points in ${treeName(o)} rows above it: ${d.name} is one of them.`,
      };
    }
  }
  return { ok: true };
}
